export const GetAlertGroupCountsQueryParams = zod.object({
  "route": zod.array(zod.string()).optional().describe('Only these Routes (`public_id`).'),
  "integration": zod.array(zod.string()).optional().describe('Only Alert Groups with Alerts from these Integrations (`public_id`).'),
  "severity": zod.array(zod.enum(['critical', 'warning', 'info'])).optional().describe('Only these Severity levels.'),
  "urgent": zod.boolean().optional().describe('Only Urgent (true) or non-Urgent (false) Alert Groups. An Alert Group is Urgent exactly when its Severity level is critical.'),
  "resolved_by": zod.enum(['user', 'system']).optional().describe('Only Alert Groups resolved by a person or by the system.'),
  "resolve_reason": zod.enum(['resolved', 'gone', 'stale', 'integration_deleted']).optional().describe('With `resolved_by=system`: the reason.'),
  "reopened": zod.boolean().optional().describe('True: Reopen count above zero.'),
  "label": zod.array(zod.string()).optional().describe('Label filter: one Alertmanager-syntax Matcher per repeat of the parameter, combined with AND. Each value is a whole matcher: `label=namespace%3D%22payments%22&label=pod%3D~%22api-.*%22` means `namespace="payments"` and `pod=~"api-.*"`. There is no per-label shorthand. On Alert Groups the Matchers are matched against the common labels — the labels every Alert of the group has with the same value — so the filter also works on summary rows after the Alerts were removed; a label the Alerts do not share counts as absent. On the Alerts view of an Integration they are matched against each Alert\'s labels.'),
  "owner": zod.string().optional().describe('A user `public_id`, `me` (the calling User; `422` for a Service account token), or `none` for Alert Groups nobody owns, resolved ones included.'),
  "assignee": zod.string().optional().describe('Only the open Alert Groups where this User is an Assignee (C-32.FR-12, FR-18), by the User\'s `public_id`, deleted Users included; or `me`, the calling User (`422` `unsupported` for a Service account token). An Alert Group leaves it once acknowledged, snoozed or resolved. An id that names no User is `422` `unknown_id`.'),
  "team": zod.string().optional().describe('Only Alert Groups that have this Team among their Teams (C-25.FR-6), deleted or not, by its `public_id`; or `mine` for those that have any Team of the calling User ("My Teams"; `422` `unsupported` for a Service account token). An unknown Team is `422` `unknown_id`.'),
  "snoozed_no_end": zod.boolean().optional().describe('True: only Alert Groups snoozed with no end. False: every Alert Group but those.'),
  "delivery_problem": zod.boolean().optional().describe('Any Destination is Not delivered, waiting for a Broken Destination, deleted in the messenger or has a Thread not attached.'),
  "unclaimed": zod.boolean().optional().describe('Only Unclaimed Alert Groups.'),
  "from": zod.iso.datetime({"offset":true}).optional().describe('Start of the time range (RFC 3339, UTC).'),
  "to": zod.iso.datetime({"offset":true}).optional().describe('End of the time range (RFC 3339, UTC).'),
  "q": zod.string().optional().describe('Search by text in the title or `summary`, case-insensitive and matching parts of words. A `#N` typed here is the same as `number`.')
})

